CREATE TABLE IF NOT EXISTS schema_version(version int PRIMARY KEY);
CREATE TABLE organizations(id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), name text NOT NULL, currency text NOT NULL DEFAULT 'USD');
CREATE TABLE users(id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), email text UNIQUE NOT NULL);
CREATE TABLE memberships(org_id TEXT NOT NULL REFERENCES organizations, user_id TEXT NOT NULL REFERENCES users, role text NOT NULL CHECK(role IN ('admin','manager','viewer')), PRIMARY KEY(org_id,user_id));
CREATE TABLE invitations(id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), org_id TEXT NOT NULL REFERENCES organizations, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','manager','viewer')), accepted_at TEXT, expires_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now','+7 days') || '000Z')));
CREATE TABLE login_tokens(hash text PRIMARY KEY, email text NOT NULL, expires_at TEXT NOT NULL, used_at TEXT);
CREATE TABLE sessions(hash text PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users, expires_at TEXT NOT NULL);
CREATE TABLE auth_limits(key text PRIMARY KEY, hits int NOT NULL, resets_at TEXT NOT NULL);
CREATE TABLE base_resources(org_id TEXT NOT NULL REFERENCES organizations, id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), name text NOT NULL CHECK(length(name)>0), daily_hours REAL NOT NULL DEFAULT 8 CHECK(daily_hours>0 AND daily_hours<=24), location_type TEXT CHECK(location_type IN ('onshore','offshore')),company_name TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')),archived_at TEXT,deleted_at TEXT,PRIMARY KEY(org_id,id));
CREATE TABLE base_projects(org_id TEXT NOT NULL REFERENCES organizations, id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))), name text NOT NULL CHECK(length(name)>0), budget_cents INTEGER NOT NULL DEFAULT 0 CHECK(budget_cents>=0), start_date TEXT,end_date TEXT,pm_name TEXT NOT NULL DEFAULT '',version INTEGER NOT NULL DEFAULT 1,prime_resource_id TEXT,closed_date TEXT,deleted_at TEXT,FOREIGN KEY(org_id,prime_resource_id) REFERENCES base_resources(org_id,id),CHECK((start_date IS NULL AND end_date IS NULL) OR (start_date IS NOT NULL AND end_date IS NOT NULL AND end_date>=start_date)),PRIMARY KEY(org_id,id));
CREATE TABLE base_sprints(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),name text NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL CHECK(end_date>=start_date),project_id TEXT,created_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')),FOREIGN KEY(org_id,project_id) REFERENCES base_projects(org_id,id),PRIMARY KEY(org_id,id));
CREATE TABLE base_tasks(org_id TEXT NOT NULL REFERENCES organizations,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),project_id TEXT NOT NULL,jira_key text,title text NOT NULL,estimate_hours REAL NOT NULL CHECK(estimate_hours>=0),start_date TEXT NOT NULL,target_date TEXT NOT NULL CHECK(target_date>=start_date),status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','hold','done')),primary_owner_id TEXT NOT NULL,sprint_id TEXT,version int NOT NULL DEFAULT 1,PRIMARY KEY(org_id,id),UNIQUE(org_id,jira_key),FOREIGN KEY(org_id,project_id) REFERENCES base_projects(org_id,id),FOREIGN KEY(org_id,primary_owner_id) REFERENCES base_resources(org_id,id),FOREIGN KEY(org_id,sprint_id) REFERENCES base_sprints(org_id,id));
CREATE TABLE base_allocations(org_id TEXT NOT NULL,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),task_id TEXT NOT NULL,resource_id TEXT NOT NULL,day TEXT NOT NULL,hours REAL NOT NULL CHECK(hours>0 AND hours<=24),released_at TEXT,release_reason text,created_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,task_id) REFERENCES base_tasks(org_id,id),FOREIGN KEY(org_id,resource_id) REFERENCES base_resources(org_id,id));
CREATE TABLE base_rates(org_id TEXT NOT NULL,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),resource_id TEXT NOT NULL,effective_from TEXT NOT NULL,hourly_cents INTEGER NOT NULL CHECK(hourly_cents>=0),PRIMARY KEY(org_id,id),UNIQUE(org_id,resource_id,effective_from),FOREIGN KEY(org_id,resource_id) REFERENCES base_resources(org_id,id));
CREATE TABLE base_worklogs(org_id TEXT NOT NULL,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),task_id TEXT NOT NULL,resource_id TEXT NOT NULL,day TEXT NOT NULL,hours REAL NOT NULL CHECK(hours>0 AND hours<=24),hourly_cents INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,task_id) REFERENCES base_tasks(org_id,id),FOREIGN KEY(org_id,resource_id) REFERENCES base_resources(org_id,id));
CREATE TABLE base_audit_events(org_id TEXT NOT NULL,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),actor_id TEXT NOT NULL REFERENCES users,entity_id TEXT NOT NULL,action text NOT NULL,detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT ((strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')),PRIMARY KEY(org_id,id));
CREATE TABLE base_project_activities(org_id TEXT NOT NULL,id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-a'||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),project_id TEXT NOT NULL,name TEXT NOT NULL CHECK(length(trim(name))>0),start_date TEXT,end_date TEXT,version INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,project_id) REFERENCES base_projects(org_id,id),CHECK((start_date IS NULL AND end_date IS NULL) OR (start_date IS NOT NULL AND end_date IS NOT NULL AND end_date>=start_date)));
CREATE UNIQUE INDEX project_activity_name ON base_project_activities(org_id,project_id,lower(trim(name)));
CREATE TRIGGER immutable_rates_update BEFORE UPDATE ON base_rates BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
CREATE TRIGGER immutable_rates_delete BEFORE DELETE ON base_rates BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
CREATE TRIGGER immutable_worklogs_update BEFORE UPDATE ON base_worklogs BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
CREATE TRIGGER immutable_worklogs_delete BEFORE DELETE ON base_worklogs BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
CREATE TRIGGER immutable_audit_events_update BEFORE UPDATE ON base_audit_events BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
CREATE TRIGGER immutable_audit_events_delete BEFORE DELETE ON base_audit_events BEGIN SELECT RAISE(ABORT,'Historical records are append-only'); END;
INSERT INTO schema_version VALUES(1);
